import toast from 'react-hot-toast';
import { catalogData } from '../api';
import { apiConnector } from '../apiconnector';

export const getCatalogPageData = async(categoryId) => {
  const toastId = toast.loading("Loading...")
  let result = [];

  try {
    console.log("Making API request with categoryId:", categoryId);

    const response = await apiConnector("POST", catalogData.CATALOGPAGEDATA_API, {
      categoryId: categoryId,
    });

    console.log("API response:", response);

    if(!response?.data?.success) {
      throw new Error("Could not fetch category page data");
    }

    result = response?.data;
  }
  catch(error) {
    console.log("CATALOG PAGE API ERROR", error);
    toast.error(error.message || "Failed to fetch category data");

    // Return a structured error object so the component can exit loading state
    result = {
      success: false,
      message: error.message || "Failed to fetch data",
      data: null
    };
  }
  finally {
    // Always dismiss the toast to prevent it from staying on screen
    toast.dismiss(toastId);
  }

  return result;
}
